macro_rules! counters {
    ($($id:ident $name:expr,)*) => {
        #[allow(non_camel_case_types, dead_code)]
        #[derive(Clone, Copy)]
        #[repr(usize)]
        enum C { $($id,)* N }
        static NAMES: [&str; C::N as usize] = [$($name,)*];
        static CNT: [AtomicU32; C::N as usize] = [const { AtomicU32::new(0) }; C::N as usize];
    };
}

