fn bump(c: C) {
    CNT[c as usize].fetch_add(1, Ordering::Relaxed);
}

/// Install this module's replacements (called from hooks::install_all).
pub fn install() {
    let mut ok = 0u32;
    let total = 11u32;
    if replace_pinned("effect_instance_update", EIU, &EFFECT_INSTANCE_UPDATE_BODY, eiu_thunk as extern "C" fn() as usize) {
        ok += 1;
    }
    if replace_pinned("render_frame", RENDER_FRAME, &RENDER_FRAME_BODY, render_frame_entry as extern "C" fn() as usize) {
        ok += 1;
    }
    // cam_498d40 (machine-translated) showed mismatches in the 2026-11-03 whole-function test: held back.
    if false && replace_pinned(
        "cam_498d40",
        CAM_498D40,
        &CAM_498D40_BODY,
        cam_498d40_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_496be0",
        CAM_496BE0,
        &CAM_496BE0_BODY,
        cam_496be0_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    // cam_49d7a0 (machine-translated) showed mismatches in the 2026-11-03 whole-function test: held back.
    if false && replace_pinned(
        "cam_49d7a0",
        CAM_49D7A0,
        &CAM_49D7A0_BODY,
        cam_49d7a0_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_492df0",
        CAM_492DF0,
        &CAM_492DF0_BODY,
        cam_492df0_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_49ae60",
        CAM_49AE60,
        &CAM_49AE60_BODY,
        cam_49ae60_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_497a20",
        CAM_497A20,
        &CAM_497A20_BODY,
        cam_497a20_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_499190",
        CAM_499190,
        &CAM_499190_BODY,
        cam_499190_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_4938c0",
        CAM_4938C0,
        &CAM_4938C0_BODY,
        cam_4938c0_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    if replace_pinned(
        "cam_499480",
        CAM_499480,
        &CAM_499480_BODY,
        cam_499480_thunk as extern "C" fn() as usize,
    ) {
        ok += 1;
    }
    crate::log(&format!("port_big: replaced {ok}/{total} with Rust"));
}

/// Per-function call counts for the periodic log.
pub fn summary() -> String {
    if CNT.iter().all(|c| c.load(Ordering::Relaxed) == 0) {
        return String::new();
    }
    let parts: Vec<String> = (0..C::N as usize)
        .filter_map(|i| {
            let v = CNT[i].load(Ordering::Relaxed);
            (v != 0).then(|| format!("{} {v}", NAMES[i]))
        })
        .collect();
    format!("port_big: {}", parts.join(", "))
}

// --- Helpers ---------------------------------------------------------------------------------

unsafe fn rdf64(a: usize) -> f64 {
    std::ptr::read_unaligned(a as *const f64)
}

unsafe fn rw(p: usize) -> u16 {
    let v = *(p as *const u16);
    #[cfg(test)]
    difftest::note_read(p, v as u32, 2);
    v
}

/// Shadows portlib's `rd` / `rb` so the difftest can see which memory a value was read from.
#[inline(always)]
unsafe fn rd(p: usize) -> u32 {
    let v = *(p as *const u32);
    #[cfg(test)]
    difftest::note_read(p, v, 4);
    v
}

#[inline(always)]
unsafe fn rb(p: usize) -> u8 {
    let v = *(p as *const u8);
    #[cfg(test)]
    difftest::note_read(p, v as u32, 1);
    v
}

/// `call_regs` for a callee that returns on the x87 stack (popped as a qword).
unsafe fn call_regs_st0(f: usize, eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32, args: &[u32]) -> f64 {
    let mut out = 0f64;
    let block: [u32; 9] =
        [f as u32, ecx, edx, esi, edi, args.as_ptr() as u32, args.len() as u32, eax, &mut out as *mut f64 as u32];
    std::arch::asm!(
        "push ebx", "push esi", "push edi", "push ebp",
        "mov ebp, esp",
        "mov ebx, eax",
        "mov ecx, [ebx + 24]",
        "mov esi, [ebx + 20]",
        "2:",
        "test ecx, ecx",
        "jz 3f",
        "push dword ptr [esi + ecx*4 - 4]",
        "dec ecx",
        "jmp 2b",
        "3:",
        "mov ecx, [ebx + 4]", "mov edx, [ebx + 8]", "mov esi, [ebx + 12]", "mov edi, [ebx + 16]",
        "mov eax, [ebx + 28]",
        "call dword ptr [ebx]",
        "mov ecx, [ebx + 32]",
        "fstp qword ptr [ecx]",
        "mov esp, ebp",
        "pop ebp", "pop edi", "pop esi", "pop ebx",
        inout("eax") block.as_ptr() => _, lateout("ecx") _, lateout("edx") _,
        clobber_abi("C"),
    );
    out
}

/// The game's float-to-int (0xDA0140) on `x`, loaded onto ST0 as a double as the original does.
unsafe fn game_ftol(x: f64) -> i32 {
    let r: u32;
    std::arch::asm!(
        "fld qword ptr [{p}]",
        "call {f}",
        p = in(reg) &x as *const f64,
        f = in(reg) 0x00DA_0140usize,
        out("eax") r,
        clobber_abi("C"),
    );
    r as i32
}

unsafe fn floorf(v: f32) -> f64 {
    call_regs_st0(0x0042_7600, 0, 0, 0, 0, 0, &[v.to_bits()])
}

// --- effect_instance_update ---------------------------------------------------------------------

#[unsafe(naked)]
extern "C" fn eiu_thunk() {
    std::arch::naked_asm!(
        "lea ecx, [esp + 4]",
        "push ecx",
        "push edx",
        "push eax",
        "call {f}",
        "add esp, 12",
        "ret",
        f = sym eiu_entry,
    )
}

extern "C" fn eiu_entry(eax: u32, edx: u32, args: *const u32) -> u32 {
    bump(C::EiuCalls);
    unsafe { eiu(eax, edx, args) }
}

/// One timed list node, shared by both lists of the 0x100 tail: wrap the phase into [0, 1), then
/// call 0x510960 when the node's window is open.
unsafe fn eiu_node(l: usize, node: usize, m: f32, plus_one: bool, ticks: i32, wobble: u32, part: u32) {
    let n3c = rf(node + 0x3C) as f64;
    let u = if plus_one { ((m as f64 + n3c) + rdf64(0x00E5_BF40)) as f32 } else { (m as f64 + n3c) as f32 };
    let r1 = call_regs_st0(0x0049_12D0, 0, 0, 0, 0, 0, &[u.to_bits()]);
    let d = r1 - u as f64;
    let w = if d < rdf64(0x00E5_BFE0) {
        bump(C::EiuWrap);
        call_regs_st0(0x0049_12D0, 0, 0, 0, 0, 0, &[u.to_bits()]) as f32
    } else {
        u
    };
    let ci = game_ftol(floorf(w));
    let c = rd(node + 0x2C) as i32;
    wf(node + 0x3C, (w as f64 - ci as f64) as f32);
    if c < 0 || (rd(node + 0x30) as i32).wrapping_add(c) >= ticks {
        bump(C::EiuNodeCalls);
        call_regs(0x0051_0960, 0, 0, 0, 0, 0, &[l as u32, node as u32, ci as u32, wobble, part]);
    }
}

unsafe fn eiu(cur_pos: u32, prev_mat: u32, a: *const u32) -> u32 {
    let arg = |n: usize| -> u32 { *a.add(n - 1) };
    let l = arg(1) as usize;
    if l == 0 || rb(l + 0x9C) & 1 == 0 {
        bump(C::EiuInactive);
        return 0;
    }
    let g = rd(l) as usize;
    let d = rd(l + 4).wrapping_mul(192).wrapping_add(rd(g + 0x2C)) as usize;
    let cur_mat = arg(2);
    let frac = f32::from_bits(arg(3));
    let prev_pos = arg(4);
    let prev_frac = f32::from_bits(arg(5));
    let looped = arg(6) as u8;
    let buf = arg(7) as usize;
    let wobble = arg(8);
    let al = arg(9) as u8;
    let t = f32::from_bits(arg(10));
    let part = arg(11);

    wf(l + 0x98, frac);
    // Argument 3 of 0x50EF90 and its 6th (stack slot S): both T * G[0x10] when arg9 is set.
    let (f3, s) = if al != 0 {
        let v = (rf(g + 0x10) as f64 * t as f64) as f32;
        (v, v)
    } else {
        (frac, prev_frac)
    };
    call_regs(0x0050_EF90, cur_pos, 0, prev_mat, 0, 0, &[l as u32, cur_mat, f3.to_bits(), prev_pos, prev_mat, s.to_bits()]);

    // frac < 0 and prev_frac < 0 (ordered); K1 < frac and K1 < prev_frac (strict, ordered).
    let neg = frac < 0.0 && prev_frac < 0.0;
    let k1 = rdf64(0x00E5_C8A0);
    let hi = k1 < frac as f64 && k1 < prev_frac as f64;
    let raw = rd(0x0252_A3C8) as i32;
    let mut x = raw as f64;
    if raw < 0 {
        x += rf(0x00E5_BFD8) as f64;
    }
    x = x / rdf64(0x00E5_C0D8) * rdf64(0x00E5_BF60);
    let ticks = game_ftol(x);
    let g10 = rf(rd(l) as usize + 0x10);
    let lp = (prev_frac as f64 * g10 as f64) as f32;
    let lc = (frac as f64 * g10 as f64) as f32;
    if neg || hi {
        bump(C::EiuSignOut);
        return 0;
    }

    let cnt = rd(d + 0x9C);
    let keys = rd(d + 0xA0);
    let res: i32;
    if rb(l + 0x9D) & 1 != 0 && 0.0f32 == rf(d + 0x50) {
        // Path A (0x50F9AE): search the list at +0xAC for this part id.
        bump(C::EiuPathA);
        let head = rd(l + 0xAC);
        let mut found = false;
        if head != 0 {
            let mut n = head;
            loop {
                if rd(n as usize + 0x34) == part {
                    found = true;
                    break;
                }
                n = rd(n as usize + 4);
                if n == head || n == 0 {
                    break;
                }
            }
        }
        if found {
            bump(C::EiuAFound);
            res = 0;
        } else if (cnt as i32) <= 0 {
            bump(C::EiuAEmpty);
            res = 0;
        } else {
            bump(C::EiuAFloor);
            let fl = floorf(rf(keys as usize + 4));
            res = game_ftol(fl);
        }
    } else {
        let y: f64;
        if al != 0 {
            let v1 = call_regs_st0(0x0051_4F80, 0, 0, 0, cnt, 0, &[t.to_bits(), keys]);
            if looped != 0 {
                bump(C::EiuB1);
                let tmp = (g10 as f64 - lp as f64) + lc as f64;
                y = (v1 * tmp) as f32 as f64;
            } else {
                bump(C::EiuB2);
                y = ((lc as f64 - lp as f64) * v1) as f32 as f64;
            }
        } else if looped != 0 {
            bump(C::EiuC1);
            let r1 = call_regs_st0(0x0051_5020, cnt, 0, 0, 0, keys, &[lp.to_bits(), g10.to_bits()]) as f32;
            let r2 = call_regs_st0(0x0051_5020, cnt, 0, 0, 0, keys, &[0f32.to_bits(), lc.to_bits()]);
            y = (r2 + r1 as f64) as f32 as f64;
        } else {
            bump(C::EiuC2);
            y = call_regs_st0(0x0051_5020, cnt, 0, 0, 0, keys, &[lp.to_bits(), lc.to_bits()]);
        }
        let z = (y + rf(l + 0xA4) as f64) as f32;
        let r1 = call_regs_st0(0x0049_12D0, 0, 0, 0, 0, 0, &[z.to_bits()]);
        let dd = r1 - z as f64;
        let w = if dd < rdf64(0x00E5_BFE0) {
            bump(C::EiuWrap);
            call_regs_st0(0x0049_12B0, 0, 0, 0, 0, 0, &[z.to_bits()]) as f32
        } else {
            z
        };
        let ci = game_ftol(floorf(w));
        wf(buf, (w as f64 - ci as f64) as f32);
        res = ci;
    }

    if rw(l + 0x9C) & 0x100 == 0 {
        bump(C::EiuTail);
        call_regs(0x0050_FD40, 0, 0, 0, 0, 0, &[l as u32, res as u32, wobble, 0, 0, 0, 0]);
        return res as u32;
    }

    bump(C::EiuBig);
    let g2 = rd(l) as usize;
    let s = if (rd(g2 + 4) as i32) < 11 { rf(0x00E1_D904) } else { rf(d + 8) };
    let m = ((lc as f64 - lp as f64) * s as f64) as f32;
    call_regs(0x0051_05E0, 0, 0, 0, 0, 0, &[l as u32, res as u32, part]);

    let head1 = rd(l + 0xAC) as usize;
    if head1 != 0 {
        let mut n = head1;
        loop {
            bump(C::EiuList1);
            eiu_node(l, n, m, false, ticks, wobble, part);
            n = rd(n + 4) as usize;
            if n == rd(l + 0xAC) as usize || n == 0 {
                break;
            }
        }
    }
    let head2 = rd(l + 0xB4) as usize;
    if head2 != 0 {
        let mut n = head2;
        loop {
            bump(C::EiuList2);
            eiu_node(l, n, m, true, ticks, wobble, part);
            n = rd(n + 4) as usize;
            if n == rd(l + 0xB4) as usize || n == 0 {
                break;
            }
        }
    }
    res as u32
}


// --- render_frame -------------------------------------------------------------------------------

extern "C" fn render_frame_entry() {
    bump(C::RfCalls);
    unsafe { render_frame() }
}

/// profile_start (0xC0BE10): ECX = label, stdcall (u32 *id).
unsafe fn pstart(label: u32, slot: *mut u32) {
    call_regs(0x00C0_BE10, 0, label, 0, 0, 0, &[slot as u32]);
}

/// profile_stop (0xC0C990): stdcall (u32 *id).
unsafe fn pstop(slot: *mut u32) {
    call_regs(0x00C0_C990, 0, 0, 0, 0, 0, &[slot as u32]);
}

/// The shadow flag: (`[0x2526CCC]` != 0) and bit 0x2000 of view 0's flags `[0x2612D18]`.
unsafe fn shadow_flag() -> bool {
    rd(0x0252_6CCC) != 0 && (rd(0x0261_2D18) >> 13) & 1 != 0
}

/// The screen-size block pointer from the render context: `[ctx+0x60]`, swapped for 0xEC2610
/// when the byte at +0x5C is 0 and it equals 0xEC26A0. Returns (size[0], size[1]).
unsafe fn screen_size(ebp: usize) -> (u32, u32) {
    let cl = rb(ebp + 0x5C);
    let mut p = rd(ebp + 0x60);
    if cl == 0 && p == 0x00EC_26A0 {
        p = 0x00EC_2610;
    }
    let obj = rd(p as usize) as usize;
    (rd(obj), rd(obj + 4))
}

unsafe fn render_frame() {
    // Profile id slots at the original's frame offsets 0x14 / 0x18 / 0x20 (index 0 / 1 / 3).
    let mut slots = [0u32; 4];
    let s14 = slots.as_mut_ptr();
    let s18 = s14.add(1);
    let s20 = s14.add(3);

    pstart(0x00DE_2468, s14);

    // Step 1: save the render-target pair, point [0x22FDCAC] at the first block, 0x529EB0.
    let ecx = rd(0x022F_DCA0);
    let edx = rd(0x022F_DC9C);
    wd(0x022F_DCB4, ecx);
    wd(0x022F_DCB0, edx);
    wd(0x022F_DCAC, 0x022F_D8E4);
    call(0x0052_9EB0);

    let shadow = shadow_flag();
    if shadow {
        bump(C::RfShadow);
    }

    // Step 3: screenshot ring.
    if rb(0x0297_5A5C) & 2 != 0 {
        bump(C::RfShot);
        let q = rd(0x0297_5940).wrapping_add(1);
        let r = call_regs(0x00D1_C530, 0, 3, q % 3, 0, 0, &[(q % 3).wrapping_add(0xC), 0x0297_591C, 0]);
        wd(0x0297_5914, r);
    }

    call(0x0072_8C40);
    call(0x0052_A4F0);

    pstart(0x00DE_2470, s20);
    call(0x0052_85F0);
    pstop(s20);
    pstop(s14);
    let q = rd(0x0297_5940).wrapping_add(1);
    call_regs(0x00D1_CB00, 0, 3, q % 3, 0, 0, &[(q % 3).wrapping_add(0xC)]);

    pstart(0x00DE_2484, s14);
    call(0x00D1_C780);
    pstop(s14);

    pstart(0x00DE_2494, s18);
    pstart(0x00DE_249C, s14);
    call(0x00D0_0F20);
    pstop(s14);
    wd(0x0252_95F0, rd(0x0252_95F0).wrapping_add(1));
    if shadow {
        call(0x0053_80A0);
    }
    call_regs(0x00D1_A070, 0, 0x0252_73C4, 0, 0, 0, &[]);
    call(0x009F_0BA0);

    pstart(0x00DE_24A8, s14);
    call(0x0053_3C00);
    pstop(s14);

    if rb(0x0252_73F3) != 0 {
        bump(C::RfPose);
        call(0x0053_1840);
        wb(0x0252_73F2, 0);
    }
    calls(&[0x009E_F600, 0x00B7_82B0, 0x00D1_AFA0, 0x00D1_A280]);

    // Lighting centre in the render context (thread slot 0 of the TLS array at fs:[0x2C]).
    let tls: u32;
    std::arch::asm!("mov {}, fs:[0x2c]", out(reg) tls);
    let ebp = rd(tls as usize) as usize;
    let t1 = rf(0x0277_C9D4);
    let t2 = rf(0x0277_C9D8);
    let ctx = rd(ebp + 0x58) as usize;
    wf(ctx + 0x5C0, rf(0x0277_C9D0));
    wf(ctx + 0x5C4, t1);
    wf(ctx + 0x5C8, t2);
    wf(ctx + 0x5CC, 0.0);
    wf(ctx + 0x6E4, rf(0x00E9_896C));
    if rb(0x0279_48A8) != 0 {
        bump(C::RfSun);
        call_regs(0x00B7_8150, 0, 0, 0, 0, 0, &[rf(0x0279_48B0).to_bits()]);
        if shadow_flag() {
            bump(C::RfLightSnap);
            call_regs(0x00B7_8190, 0x00E9_D690, 0, 0, 0, 0x00E9_D6C0, &[0x00E9_D69C, 0x00E9_D6B0]);
        } else {
            bump(C::RfLightDef);
            call_regs(0x00B7_8190, 0x00EC_5ACC, 0, 0, 0, 0x0252_A6F0, &[0x00EC_5ACC, 0x0252_A6F0]);
        }
    }

    pstart(0x00DE_24B4, s14);
    wb(0x0252_A338, 1);
    call(0x0052_8820);
    wb(0x0252_A338, 0);
    pstop(s14);
    pstop(s18);

    pstart(0x00DE_24C0, s14);
    let (s0, s1) = screen_size(ebp);
    call_regs(0x00D1_4D20, 0, 0, 0, s0, 0, &[0, s1]);
    let (w0, w1) = screen_size(ebp);
    call_regs(0x00D1_A400, 0, 0, 0, 0, 0, &[(w0 as i32 as f32).to_bits(), (w1 as i32 as f32).to_bits()]);
    wb(0x0252_A338, 1);
    call(0x0052_8A10);
    wb(0x0252_A338, 0);
    pstop(s14);

    pstart(0x00DE_24C8, s14);
    call(0x00AE_1090);
    pstart(0x00DE_24D0, s18);
    call(0x0052_7A60);
    pstop(s18);
    pstart(0x00DE_24DC, s18);
    wf(0x00E9_8D74, rf(0x00E5_C340));
    if rb(0x0252_73E4) != 0 && rb(0x00E9_4D37) != 0 {
        bump(C::RfCopy518810);
        call(0x0051_8810);
    }
    wb(0x00E9_4D37, 1);
    call(0x0052_7020);
    pstop(s18);
    if rb(0x027A_3F18) != 0 {
        bump(C::RfTag);
        call(0x0062_5620);
    }
    calls(&[0x0073_8E80, 0x0052_93D0]);

    pstart(0x00DE_24E8, s18);
    call_regs(0x00D1_4700, 0, 0, 0, 0x00E9_D670, 0, &[]);
    calls(&[0x00A8_B440, 0x004C_7290, 0x004C_32F0, 0x004C_FC60, 0x008A_B9E0]);
    call_regs(0x00D1_A4D0, 0, 0, 0, 0, 0, &[0]);
    pstop(s18);
    pstop(s14);

    pstart(0x00DE_24F4, s18);
    if rb(0x0252_73B4) != 0 {
        bump(C::RfPost1);
        call_regs(0x0051_CF40, 0, 0, 0, 0, 0, &[0]);
        call(0x00D1_E140);
        let edx = rd(0x022F_DCA8);
        let eax = rd(0x022F_DCA4);
        wd(0x022F_DCB4, edx);
        wd(0x022F_DCB0, eax);
    } else {
        bump(C::RfPost2);
        // {[0xFA2228], [0xFA222C], byte 0} at frame offset 0x24.
        let mut blk = [0u32; 3];
        blk[0] = rd(0x00FA_2228);
        blk[1] = rd(0x00FA_222C);
        call_regs(0x0051_CF40, 0, 0, 0, 0, 0, &[0]);
        call_regs(0x0051_7BB0, 0, 0, 0, blk.as_mut_ptr() as u32, 0, &[]);
        call(0x00D1_E140);
        call_regs(0x0051_8CA0, 0, 0, 0, blk.as_mut_ptr() as u32, 0, &[blk.as_mut_ptr() as u32]);
        let ecx = rd(0x022F_DCA8);
        let edx = rd(0x022F_DCA4);
        wd(0x022F_DCB4, ecx);
        wd(0x022F_DCB0, edx);
    }
    wd(0x022F_DCAC, 0x022F_DC1C);
    call(0x0051_7D40);
    pstop(s18);
    call(0x0052_11F0);
}

